const fixture = path.join(__dirname, 'sample.txt');

function run(args) {
  return spawnSync(process.execPath, [cli, ...args], {
    encoding: 'utf8',
    timeout: 5000,
  });
}

test('CLI prints the top N case-insensitive words in frequency and tie order', () => {
  const result = run([fixture, '3']);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, 'apple 3\nbanana 2\npear 2\n');
});

test('--min-length defaults to one and N limits the output', () => {
  const result = run([fixture, '2']);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, 'apple 3\nbanana 2\n');
});

test('--min-length excludes shorter tokens before ranking', () => {
  const result = run([fixture, '10', '--min-length', '5']);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, 'apple 3\nbanana 2\n');
});

test('--min-length accepts the option before positional N', () => {
  const result = run([fixture, '--min-length', '6', '10']);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, 'banana 2\\n');
});

test('invalid --min-length exits unsuccessfully with an error', () => {
  const result = run([fixture, '3', '--min-length', '0']);
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /--min-length must be a positive integer/);
});

test('missing input file exits unsuccessfully with an error', () => {
  const missing = path.join(os.tmpdir(), `wordfreq-missing-${process.pid}.txt`);
  const result = run([missing, '3']);
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /ENOENT/);
});

#!/usr/bin/env node
'use strict';

/**
 * Return the most frequent words in text as [{ word, count }, ...].
 * Tokens consist of Unicode letters or numbers, optionally joined by
 * straight/curly apostrophes when another letter/number follows. Words are
 * case-insensitive (normalized to lowercase); words are ordered by frequency
 * descending, then alphabetically using code-point order.
 *
 * @param {string} text
 * @param {number} n Maximum number of words to return (non-negative integer).
 * @param {object} [options]
 * @param {number} [options.minLength=1] Minimum token length in Unicode code
 *   points; must be a positive integer.
 * @returns {{word: string, count: number}[]}
 */
function topWords(text, n, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isSafeInteger(n) || n < 0) {
    throw new RangeError('n must be a non-negative integer');
  }
  const minLength = options.minLength === undefined ? 1 : options.minLength;
  if (!Number.isSafeInteger(minLength) || minLength < 1) {
    throw new RangeError('minLength must be a positive integer');
  }

  const counts = new Map();
  // A token starts and ends in a Unicode letter/number. Internal apostrophes
  // are retained only when followed by another letter/number (e.g. don't).
  const tokens = text.match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) || [];
  for (const token of tokens) {
    const word = token.toLowerCase();
    if ([...word].length < minLength) continue;
    counts.set(word, (counts.get(word) || 0) + 1);
  }

  return [...counts]
    .map(([word, count]) => ({ word, count }))
    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
    .slice(0, n);
}

function usage() {
  return 'Usage: node wordfreq.js <file> [n] [--min-length <positive-integer>]';
}

function parseArgs(args) {
  let file;
  let n = 10;
  let nProvided = false;
  let minLength = 1;

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--min-length') {
      if (i + 1 >= args.length || args[i + 1].startsWith('--')) {
        throw new Error('--min-length requires a positive integer');
      }
      const value = args[++i];
      if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || Number(value) < 1) {
        throw new Error('--min-length must be a positive integer');
      }
      minLength = Number(value);
    } else if (arg.startsWith('--')) {
      throw new Error(`unknown option: ${arg}`);
    } else if (file === undefined) {
      file = arg;
    } else if (!nProvided) {
      if (!/^\d+$/.test(arg) || !Number.isSafeInteger(Number(arg))) {
        throw new Error('n must be a non-negative integer');
      }
      n = Number(arg);
      nProvided = true;
    } else {
      throw new Error(`unexpected argument: ${arg}`);
    }
  }
  if (file === undefined) throw new Error('a text file is required');
  return { file, n, minLength };
}

if (require.main === module) {
  const fs = require('node:fs');
  try {
    const { file, n, minLength } = parseArgs(process.argv.slice(2));
    const text = fs.readFileSync(file, 'utf8');
    for (const { word, count } of topWords(text, n, { minLength })) {
      process.stdout.write(`${word} ${count}\n`);
    }
  } catch (error) {
    process.stderr.write(`${usage()}\nError: ${error.message}\n`);
    process.exitCode = 1;
  }
}

module.exports = { topWords };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const ROOT = path.resolve(__dirname, '..');
const SCRIPT = path.join(ROOT, 'wordfreq.js');
const FIXTURE = path.join(__dirname, 'sample.txt');

function run(args, options = {}) {
  return spawnSync(process.execPath, [SCRIPT, ...args], {
    cwd: ROOT,
    encoding: 'utf8',
    ...options,
  });
}

function withTextFile(contents, callback) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'wordfreq-test-'));
  const file = path.join(dir, 'input.txt');
  fs.writeFileSync(file, contents, 'utf8');
  try {
    callback(file);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

test('counts words, normalizes case, and orders by descending frequency', () => {
  const result = run([FIXTURE, '10']);
  assert.equal(result.status, 0, result.stderr);
  assert.match(result.stdout, /^apple\s+3\b/m);
  assert.match(result.stdout, /^banana\s+2\b/m);
  assert.match(result.stdout, /^pear\s+1\b/m);
  const counts = [...result.stdout.matchAll(/\s(\d+)\s*$/gm)].map((m) => Number(m[1]));
  assert.deepEqual(counts, [...counts].sort((a, b) => b - a));
});

test('breaks frequency ties alphabetically', () => {
  withTextFile('zebra apple banana apple banana zebra\n', (file) => {
    const result = run([file, '3']);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(result.stdout.trim().split(/\r?\n/), [
      'apple 2',
      'banana 2',
      'zebra 2',
    ]);
  });
});

test('tokenizes punctuation-delimited words and lowercases them', () => {
  withTextFile("Hello, HELLO! can't; café 42_world.\n", (file) => {
    const result = run([file, '20']);
    assert.equal(result.status, 0, result.stderr);
    const rows = result.stdout.trim().split(/\r?\n/);
    assert.deepEqual(rows, ['hello 2', '42 1', 'café 1', "can't 1", 'world 1']);
  });
});

test('limits output to the requested number of words', () => {
  const result = run([FIXTURE, '2']);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout.trim().split(/\r?\n/).length, 2);
});

test('--min-length defaults to 1 and excludes shorter words when configured', () => {
  withTextFile('a an ant bee be\n', (file) => {
    const defaults = run([file, '10']);
    assert.equal(defaults.status, 0, defaults.stderr);
    assert.deepEqual(defaults.stdout.trim().split(/\r?\n/), [
      'a 1', 'an 1', 'ant 1', 'be 1', 'bee 1',
    ]);

    const filtered = run([file, '10', '--min-length', '3']);
    assert.equal(filtered.status, 0, filtered.stderr);
    assert.deepEqual(filtered.stdout.trim().split(/\r?\n/), ['ant 1', 'bee 1']);
  });
});

test('accepts --min-length before positional arguments', () => {
  withTextFile('x yak ox yak\n', (file) => {
    const result = run(['--min-length', '3', file, '10']);
    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stdout.trim(), 'yak 2');
  });
});

test('reports missing input files as a nonzero CLI error', () => {
  const result = run([path.join(os.tmpdir(), 'wordfreq-file-that-does-not-exist'), '3']);
  assert.notEqual(result.status, 0);
  assert.ok(result.stderr.length > 0, 'expected an error message on stderr');
});

test('rejects invalid count arguments', () => {
  const result = run([FIXTURE, 'not-a-number']);
  assert.notEqual(result.status, 0);
  assert.ok(result.stderr.length > 0, 'expected an error message on stderr');
});

